sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_grid;
uniform float amzp_edgeMode;
uniform float amzp_feather;
uniform float amzp_showGrid;
uniform float2 amzp_m00;
uniform float2 amzp_m01;
uniform float2 amzp_m02;
uniform float2 amzp_m03;
uniform float2 amzp_m04;
uniform float2 amzp_m10;
uniform float2 amzp_m11;
uniform float2 amzp_m12;
uniform float2 amzp_m13;
uniform float2 amzp_m14;
uniform float2 amzp_m20;
uniform float2 amzp_m21;
uniform float2 amzp_m22;
uniform float2 amzp_m23;
uniform float2 amzp_m24;
uniform float2 amzp_m30;
uniform float2 amzp_m31;
uniform float2 amzp_m32;
uniform float2 amzp_m33;
uniform float2 amzp_m34;
uniform float2 amzp_m40;
uniform float2 amzp_m41;
uniform float2 amzp_m42;
uniform float2 amzp_m43;
uniform float2 amzp_m44;
uniform float amzp_overdrawOn;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 srcAt(float2 d) { return amzTexture(0, l2s(float2(d.x, 1.0 - d.y))); }
    void crw5(float u, float n, out float w0, out float w1, out float w2, out float w3, out float w4) {
        float x = u * (n - 1.0);
        float i = clamp(floor(x), 0.0, n - 2.0);
        float f = x - i;
        float f2 = f * f, f3 = f2 * f;
        float bm = 0.5 * (-f3 + 2.0 * f2 - f);
        float b0 = 0.5 * (3.0 * f3 - 5.0 * f2 + 2.0);
        float b1 = 0.5 * (-3.0 * f3 + 4.0 * f2 + f);
        float b2 = 0.5 * (f3 - f2);
        if (i < 0.5) { b0 += 2.0 * bm; b1 -= bm; bm = 0.0; }
        if (i + 2.0 > n - 0.5) { b1 += 2.0 * b2; b0 -= b2; b2 = 0.0; }
        float4 b = float4(bm, b0, b1, b2);
        w0 = dot(b, float4(equal(float4(0.0) - i + 1.0, float4(0.0, 1.0, 2.0, 3.0))));
        w1 = dot(b, float4(equal(float4(1.0) - i + 1.0, float4(0.0, 1.0, 2.0, 3.0))));
        w2 = dot(b, float4(equal(float4(2.0) - i + 1.0, float4(0.0, 1.0, 2.0, 3.0))));
        w3 = dot(b, float4(equal(float4(3.0) - i + 1.0, float4(0.0, 1.0, 2.0, 3.0))));
        w4 = dot(b, float4(equal(float4(4.0) - i + 1.0, float4(0.0, 1.0, 2.0, 3.0))));
    }
    float gridN() { return clamp(floor(amzp_grid + 0.5), 3.0, 5.0); }
    float2 disp(float2 s) {
        float n = gridN();
        float2 u = clamp(s, 0.0, 1.0);
        float a0, a1, a2, a3, a4, c0, c1, c2, c3, c4;
        crw5(u.x, n, a0, a1, a2, a3, a4);
        crw5(u.y, n, c0, c1, c2, c3, c4);
        float2 r0 = a0 * amzp_m00 + a1 * amzp_m01 + a2 * amzp_m02 + a3 * amzp_m03 + a4 * amzp_m04;
        float2 r1 = a0 * amzp_m10 + a1 * amzp_m11 + a2 * amzp_m12 + a3 * amzp_m13 + a4 * amzp_m14;
        float2 r2 = a0 * amzp_m20 + a1 * amzp_m21 + a2 * amzp_m22 + a3 * amzp_m23 + a4 * amzp_m24;
        float2 r3 = a0 * amzp_m30 + a1 * amzp_m31 + a2 * amzp_m32 + a3 * amzp_m33 + a4 * amzp_m34;
        float2 r4 = a0 * amzp_m40 + a1 * amzp_m41 + a2 * amzp_m42 + a3 * amzp_m43 + a4 * amzp_m44;
        return c0 * r0 + c1 * r1 + c2 * r2 + c3 * r3 + c4 * r4;
    }
    float2 inv(float2 p) {
        float2 s = p;
        for (int k = 0; k < 10; k++) s = p - disp(s);
        return s;
    }
    float2 tile(float2 s) {
        if (int(amzp_edgeMode) == 1) return clamp(s, 0.0, 1.0);
        if (int(amzp_edgeMode) == 2) return fract(s);
        if (int(amzp_edgeMode) == 3) { float2 m = mod(s, 2.0); return mix(m, 2.0 - m, step(1.0, m)); }
        return s;
    }
    void nmMain() {
        float2 p = float2(amzLayerNorm().x, 1.0 - amzLayerNorm().y);
        float2 s = inv(p);
        float2 d = disp(s);
        float err = length(s + d - p);
        float4 c = srcAt(clamp(tile(s), 0.0, 1.0));
        float2 px = 1.0 / max(layer, float2(1.0));
        float h = 0.002;
        float2 jx = float2(1.0, 0.0) + (disp(s + float2(h, 0.0)) - d) / h;
        float2 jy = float2(0.0, 1.0) + (disp(s + float2(0.0, h)) - d) / h;
        float det = jx.x * jy.y - jy.x * jx.y;
        if (abs(det) < 1e-6) det = 1e-6;
        float2 ix = float2(jy.y, -jx.y) / det;
        float2 iy = float2(-jy.x, jx.x) / det;
        float2 fw = max(abs(ix * px.x) + abs(iy * px.y), float2(1e-6));
        if (int(amzp_edgeMode) == 0) {
            float2 e = min(s, 1.0 - s) / fw;
            float f = max(amzp_feather * pxs(), 0.75);
            c *= clamp((min(e.x, e.y) + 0.5) / f, 0.0, 1.0);
        }
        if (err > 0.01) c = float4(0.0);
        if ((amzp_showGrid>0.5)) {
            float n = gridN() - 1.0;
            float2 g = abs(fract(s * n + 0.5) - 0.5) / (fw * n);
            float l = 1.0 - clamp(min(g.x, g.y) - 0.5, 0.0, 1.0);
            bool inside = s.x > -0.001 && s.x < 1.001 && s.y > -0.001 && s.y < 1.001;
            if (inside) c = mix(c, float4(0.0, 1.0, 0.66, 1.0), l * 0.85);
        }
        amzOutput = c;
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
